/* Forecut collection workspace. All collection data stays in this origin's local storage. */
(function(){
'use strict';
// Older cached page shells may not yet include the colour reference module.
if(!window.ForecutColourLibrary){const dependency=document.createElement('script');dependency.src='tools/colour-library.js?v=redesign-20261111';const self=document.currentScript?.src||'tools/app.js?v=redesign-20261111';dependency.onload=()=>{const retry=document.createElement('script');retry.src=self;document.head.appendChild(retry);};dependency.onerror=()=>{const status=document.getElementById('status');if(status)status.textContent='Please reload to finish loading the colour tools.';};document.head.appendChild(dependency);return;}
const M=window.ForecutMath, $=s=>document.querySelector(s), app=$('#app');
const KEY='fc-collection-workspace-v1';
const titles={pricefold:['Price & Profit Calculator','Price with the whole picture.','Build your product cost, allow for selling fees and returns, and find a price that works.'],rangeboard:['Collection Planner','Give your collection a plan.','Balance styles, colourways, quantities and price points before you commit to production.'],swatchsmith:['Colour Palette Builder','Find your collection’s colours.','Start with a Forecut forecast or create a palette of your own. Save colours, assign roles and share a swatch sheet.'],evenpoint:['Break-even Calculator','Know what needs to sell.','Compare order quantities and sell-through before placing your production order.'],cutclock:['Production Calendar','Make time for every step.','Start with your launch date and work backward through sourcing, sampling and production.']};
let current=document.body.dataset.tool,saveFailed=false;
const uid=()=>globalThis.crypto?.randomUUID?.()||'fc-'+Date.now()+'-'+Math.random().toString(16).slice(2);
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(n);
const num=n=>new Intl.NumberFormat('en-IN',{maximumFractionDigits:1}).format(n);
const pct=n=>num(n*100)+'%';
const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
function futureDate(){const d=new Date();d.setDate(d.getDate()+100);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
const defaultPrice=()=>({fabric:300,stitching:180,trims:35,packaging:25,other:0,overhead:10,mrp:1499,tax:0,commission:0,gateway:2,fixed:0,forward:70,reverse:70,returns:10,resale:90,refundedFees:100,discount:0,feeTax:0,claimCredit:false,basis:'net',target:40,ending9:true});
const defaultTasks=()=>[['Design freeze',2],['Fabric sourcing & order',7],['Lab dip & approval',5],['First sample',7],['Fit review & approval',3],['Size set approval',4],['Bulk fabric receipt',7],['Cutting',3],['Sewing',10],['Finishing & quality check',4],['Packing',2],['Dispatch & transit',4],['Listings ready / launch',1]].map(([name,days])=>({id:uid(),name,days}));
function defaults(){return {version:1,name:'My collection',styles:[],activeStyle:'',price:defaultPrice(),range:{season:'SS27',market:'India',sellThrough:75,budget:150000,plannedStyles:10,shares:[40,25,20,15]},palette:[{id:uid(),name:'Forest',hex:'#264d3a',role:'Core'},{id:uid(),name:'Cream',hex:'#efe9dc',role:'Core'},{id:uid(),name:'Clay',hex:'#b4532a',role:'Accent'}],paletteSource:'Custom palette',pantoneLibrary:[],even:{fixed:15000,variable:594,proceeds:850,quantity:100,sellThrough:75,recovery:0,linked:false},calendar:{launch:futureDate(),weekends:'sun',holidays:'',tasks:defaultTasks(),buffer:3}};}
function validateBackup(s){
 if(!s||s.version!==1||typeof s.name!=='string'||s.name.length>100||!Array.isArray(s.styles)||s.styles.length>500||!Array.isArray(s.palette)||s.palette.length>100)throw Error('This is not a supported Forecut collection backup.');
 const d=defaults();
 for(const k of ['price','range','even','calendar'])if(!s[k]||typeof s[k]!=='object')throw Error('Backup is missing '+k+'.');
 const numberKeys=(o,template)=>{for(const [k,v]of Object.entries(template))if(typeof v==='number'&&(!Number.isFinite(o[k])||o[k]<0))throw Error('Invalid number in backup: '+k);};
 numberKeys(s.price,d.price);numberKeys(s.range,{sellThrough:75,budget:0,plannedStyles:10});numberKeys(s.even,d.even);
 if(!Array.isArray(s.range.shares)||s.range.shares.length!==4||s.range.shares.some(x=>!Number.isFinite(x)||x<0||x>100))throw Error('Invalid category shares.');
 if(!Array.isArray(s.calendar.tasks)||s.calendar.tasks.length>100||!s.calendar.tasks.length)throw Error('Invalid task list.');
 const safeId=x=>typeof x==='string'&&/^[a-zA-Z0-9-]{1,80}$/.test(x);
 const unique=new Set();s.styles.forEach(t=>{if(!safeId(t.id)||unique.has(t.id)||typeof t.name!=='string'||!t.priceSettings)throw Error('Invalid style record.');unique.add(t.id);numberKeys(t,{colours:1,sizes:1,perSku:1,price:1,cost:1});['colours','sizes','perSku'].forEach(k=>{if(!Number.isInteger(t[k])||t[k]<1||t[k]>100000)throw Error('Invalid style quantities.');});numberKeys(t.priceSettings,d.price);M.price(priceInputs(t.priceSettings));});
 s.palette.forEach(c=>{M.rgb(c.hex);if(!safeId(c.id)||typeof c.name!=='string'||!['Core','Accent','Print ground','Print colour'].includes(c.role))throw Error('Invalid palette colour.');});
 if(s.pantoneLibrary!==undefined){if(!Array.isArray(s.pantoneLibrary)||s.pantoneLibrary.length>5000)throw Error('Invalid colour reference library.');s.pantoneLibrary=s.pantoneLibrary.map(ForecutColourLibrary.validateEntry);}
 s.palette.forEach(c=>{if(c.pantoneCode){c.pantoneSystem=ForecutColourLibrary.normalizeSystem(c.pantoneSystem);c.pantoneCode=ForecutColourLibrary.codeValue(c.pantoneCode,c.pantoneSystem);}if(c.pantoneName!==undefined&&(typeof c.pantoneName!=='string'||c.pantoneName.length>120))throw Error('Invalid colour reference name.');});
 M.price(priceInputs(s.price));M.breakEven({...s.even,sellThrough:s.even.sellThrough/100,recovery:s.even.recovery/100});
 if(!['sun','sat-sun','none'].includes(s.calendar.weekends)||typeof s.calendar.holidays!=='string')throw Error('Invalid working calendar.');
 if(s.calendar.tasks.some(t=>!safeId(t.id)||typeof t.name!=='string'))throw Error('Invalid task record.');
 M.schedule(s.calendar.launch,s.calendar.tasks,weekends(s.calendar.weekends),holidayList(s.calendar.holidays));
 return s;
}
let state=defaults();try{const raw=localStorage.getItem(KEY);if(raw)state=validateBackup(JSON.parse(raw));}catch(e){saveFailed=true;$('#status').textContent='Saved data could not be loaded. Your existing browser data has not been overwritten. Download a backup before restoring or saving a new collection.';}
function save(){try{if(saveFailed)return;localStorage.setItem(KEY,JSON.stringify(state));$('#status').textContent='Saved in this browser · '+new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});}catch(e){$('#status').textContent='Browser storage unavailable or full. Download a backup to keep your work.';}}
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500);}
function download(name,data,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function csv(name,rows){const cell=x=>{let s=String(x??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};download(name,'\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
const slug=()=>state.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,60)||'forecut-collection';
const metric=(label,value,note='',bad=false)=>`<div class="metric${bad?' bad':''}"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`;
const field=(label,key,value,{type='number',min=0,max,step='any',scope='',suffix=''}={})=>`<label>${label}${suffix}<input data-field="${key}" ${scope?`data-scope="${scope}"`:''} type="${type}" value="${escape(value)}" ${type==='number'?`required min="${min}" step="${step}" ${max!==undefined?`max="${max}"`:''}`:''} ${type==='text'?'maxlength="150"':''}></label>`;
const select=(label,key,value,options,scope='')=>`<label>${label}<select data-field="${key}" ${scope?`data-scope="${scope}"`:''}>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${escape(v)}" ${v===value?'selected':''}>${escape(l)}</option>`;}).join('')}</select></label>`;
const printButton='<button data-action="print">Print / save PDF</button>';
function heading(){const [name,title,intro]=titles[current];return `<span class="eyebrow">${name} / ${state.range.season?escape(state.range.season):'Collection tools'}</span><h1>${title}</h1><p class="intro">${intro}</p>`;}
function styleChooser(){return `<div class="panel-head no-print"><label style="min-width:240px">Working style<select id="styleSelect"><option value="">Standalone calculation</option>${state.styles.map(s=>`<option value="${s.id}" ${s.id===state.activeStyle?'selected':''}>${escape(s.name)}</option>`).join('')}</select></label><a class="button small" href="rangeboard.html" data-go="rangeboard">Manage styles →</a></div>`;}
function productCost(p){return (p.fabric+p.stitching+p.trims+p.packaging+p.other)*(1+p.overhead/100);}
function priceInputs(p){return {cost:productCost(p),mrp:p.mrp,tax:p.tax/100,commission:p.commission/100,gateway:p.gateway/100,fixed:p.fixed,forward:p.forward,reverse:p.reverse,returns:p.returns/100,resale:p.resale/100,refundedFees:p.refundedFees/100,discount:p.discount/100,feeTax:p.feeTax/100,claimCredit:p.claimCredit,basis:p.basis};}
function syncPrice(){const s=state.styles.find(x=>x.id===state.activeStyle);if(s){s.priceSettings={...state.price};s.cost=productCost(state.price);s.price=state.price.mrp;}}
function priceView(){const p=state.price;
 return `${styleChooser()}<section class="panel"><div class="panel-head"><h2>01 / Make the product</h2><span class="badge">INR · per piece</span></div><div class="fields">${[['Fabric / piece','fabric'],['Stitching / CMT','stitching'],['Trims & decoration','trims'],['Packaging','packaging'],['Other direct costs','other'],['Overhead on direct cost (%)','overhead']].map(([l,k])=>field(l,k,p[k],{scope:'price'})).join('')}</div></section>
 <section class="panel"><h2>02 / Choose your selling assumptions</h2><div class="fields">${[['MRP, including product tax','mrp'],['Planned discount (%)','discount'],['Product tax (%) — enter your rate','tax'],['Channel commission (%)','commission'],['Payment fee (%) of sale incl. tax','gateway'],['Fixed fee per order attempt','fixed'],['Forward shipping per attempt','forward'],['Reverse shipping per return','reverse'],['Return rate (%) of shipments','returns'],['Returned stock resellable (%)','resale'],['Transaction fees refunded on return (%)','refundedFees'],['Tax on transaction fees (%)','feeTax']].map(([l,k])=>field(l,k,p[k],{scope:'price',max:['discount','tax','commission','gateway','returns','resale','refundedFees','feeTax'].includes(k)?(k==='returns'?99.9:100):undefined})).join('')}${select('Commission calculated on','basis',p.basis,[['net','Sale excluding product tax'],['gross','Sale including product tax']],'price')}<label class="check"><input type="checkbox" data-field="claimCredit" data-scope="price" ${p.claimCredit?'checked':''}>Recover transaction-fee tax</label></div><p class="note">Rates start as editable examples, not marketplace quotations. Enter applicable tax rates yourself. One item per order; costs and recoverable credits must use a consistent tax basis. No automatic tax slabs.</p></section>
 <div id="priceResults" aria-live="polite"></div><section class="panel"><h2>03 / Find a workable price</h2><div class="fields">${field('Target contribution margin (%)','target',p.target,{scope:'price',max:99.9})}<label class="check"><input type="checkbox" data-field="ending9" data-scope="price" ${p.ending9?'checked':''}>Round MRP up to end in 9</label></div><div class="actions"><button class="primary" data-action="solve">Calculate & apply target price</button><button data-action="sendEven">Use in Break-even Calculator →</button><button data-action="priceCSV">Export cost sheet CSV</button></div><p class="note">Contribution margin is after product and channel costs, before collection-level fixed costs. It differs from markup on cost.</p><details><summary>How returns and margin are calculated</summary><div class="formula">Sale = MRP × (1 − discount)<br>Revenue = sale ÷ (1 + product tax)<br>Return attempts per kept piece = return rate ÷ (1 − return rate)<br>Return burden = attempts × (forward + reverse + unrecoverable stock cost + non-refunded transaction fees)<br>Net revenue before product cost = revenue − kept-order fees − return burden<br>Contribution = net revenue before product cost − product cost<br>Margin = contribution ÷ revenue</div></details></section>`;
}
function priceResults(){try{const x=priceInputs(state.price),r=M.price(x);$('#priceResults').innerHTML=`<div class="metrics">${metric('Product cost',money(r.cost),'Including your overhead')}${metric('Contribution / kept piece',money(r.contribution),'After fees, returns and product cost',r.contribution<0)}${metric('Contribution margin',pct(r.margin),'On sale revenue excluding product tax',r.margin<0)}</div><section class="panel"><h2>Where the money goes</h2><div class="table-scroll"><table><thead><tr><th>Per kept piece</th><th>Amount</th></tr></thead><tbody>${[['Customer pays after discount',r.sale],['Revenue excluding product tax',r.revenue],['Fees & shipping on kept shipment',r.keptFees],['Expected return burden',r.returnBurden],['Net revenue before product cost',r.netRevenue],['Product cost',r.cost],['Contribution',r.contribution]].map(([k,v])=>`<tr><td>${k}</td><td>${money(v)}</td></tr>`).join('')}</tbody></table></div><h3 style="margin-top:22px">Discount scenarios</h3><table><thead><tr><th>Discount</th><th>Customer pays</th><th>Contribution</th><th>Margin</th></tr></thead><tbody>${[0,30,50].map(d=>{const r=M.price({...x,discount:d/100});return `<tr><td>${d}%</td><td>${money(r.sale)}</td><td>${money(r.contribution)}</td><td>${pct(r.margin)}</td></tr>`;}).join('')}</tbody></table></section>`;}catch(e){$('#priceResults').innerHTML=`<p class="error">${escape(e.message)}</p>`;}}
function newStyle(){return {id:uid(),name:'New style',category:'Tops',tier:'Better',stage:'Core',colours:2,sizes:4,perSku:10,price:1499,cost:productCost(defaultPrice()),drop:'',priceSettings:defaultPrice()};}
const categories=['Tops','Bottoms','Dresses','Layers','Sets','Ethnic wear','Footwear','Other'];
function rangeView(){const r=state.range;return `<section class="panel"><h2>Collection brief</h2><div class="fields">${field('Season','season',r.season,{type:'text',scope:'range'})}${field('Market / department','market',r.market,{type:'text',scope:'range'})}${field('Expected sell-through (%)','sellThrough',r.sellThrough,{scope:'range',max:100})}${field('Production budget (INR)','budget',r.budget,{scope:'range'})}</div></section><div id="rangeResults"></div>
 <section class="panel"><div class="panel-head"><h2>The style board</h2><button class="primary" data-action="addStyle">+ Add style</button></div><p class="note">Each style uses the same quantity per size / colour combination. Prices are full-price MRP; production costs exclude channel fees. Use Price & Profit Calculator for each style’s detailed costing.</p><div class="table-scroll"><table class="style-row"><thead><tr>${['Style','Category','Tier','Trend stage','Colours','Sizes','Units / SKU','MRP ₹','Cost ₹','Drop date','Actions'].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${state.styles.map(s=>`<tr data-style="${s.id}"><td><input aria-label="Style name" data-style-field="name" value="${escape(s.name)}" maxlength="100" style="min-width:140px"></td><td>${rowSelect('category',s.category,categories)}</td><td>${rowSelect('tier',s.tier,['Good','Better','Best'])}</td><td>${rowSelect('stage',s.stage,['Core','Emerging','Rising','Peaking','Fading'])}</td>${['colours','sizes','perSku','price','cost'].map(k=>`<td><input aria-label="${k}" type="number" min="${['colours','sizes','perSku'].includes(k)?1:0}" step="${['colours','sizes','perSku'].includes(k)?1:'any'}" data-style-field="${k}" value="${s[k]}"></td>`).join('')}<td><input aria-label="Drop date" type="date" data-style-field="drop" value="${escape(s.drop)}"></td><td><button class="small" data-action="priceStyle" data-id="${s.id}">Price</button> <button class="small" data-action="calendarStyle" data-id="${s.id}">Dates</button> <button class="small danger" data-action="removeStyle" data-id="${s.id}" aria-label="Remove ${escape(s.name)}">Remove</button></td></tr>`).join('')}</tbody></table></div>${state.styles.length?'':'<p class="empty">Your board is ready. Add your first style or create slots below.</p>'}<div class="actions"><button data-action="rangeCSV">Export collection CSV</button>${printButton}</div></section>
 <section class="panel"><h2>Start with a category mix</h2><div class="fields">${field('Number of new style slots','plannedStyles',r.plannedStyles,{scope:'range',step:1,min:1,max:200})}${['Tops','Bottoms','Dresses','Layers'].map((c,i)=>field(c+' (%)','share'+i,r.shares[i],{scope:'range',max:100})).join('')}</div><div class="actions"><button data-action="allocate">Add slots from this mix</button></div><p class="note">Shares must total 100%. Rounding uses largest remainders so the slot count stays exact. Existing styles are kept.</p></section>`;}
function rowSelect(k,v,opts){return `<select aria-label="${k}" data-style-field="${k}">${opts.map(o=>`<option ${o===v?'selected':''}>${escape(o)}</option>`).join('')}</select>`;}
function rangeResults(){const r=M.rangeTotals(state.styles),s=state.range;let warnings=[];if(r.cost>s.budget)warnings.push('Planned production cost exceeds your budget by '+money(r.cost-s.budget)+'.');if(state.styles.length&&state.styles.filter(x=>x.stage==='Peaking').length/state.styles.length>.4)warnings.push('More than 40% of styles use peaking trends. Review collection risk.');const missing=state.styles.filter(x=>!x.drop).length;if(missing)warnings.push(missing+' styles have no drop date.');$('#rangeResults').innerHTML=`<div class="metrics">${metric('Planned units',num(r.units),num(r.skus)+' size / colour SKUs')}${metric('Production commitment',money(r.cost),'Against '+money(s.budget)+' budget',r.cost>s.budget)}${metric('Full-price revenue',money(r.revenue),'At 100% sell-through · includes product tax')}</div><div class="panel"><div class="fields"><div><span class="note">Revenue at ${s.sellThrough}% sell-through</span><h3>${money(r.revenue*s.sellThrough/100)}</h3></div><div><span class="note">Average full-price MRP</span><h3>${money(r.average)}</h3></div><div><span class="note">Unsold units at this assumption</span><h3>${num(r.units*(1-s.sellThrough/100))}</h3></div></div>${warnings.map(w=>`<p class="notice">${escape(w)}</p>`).join('')}<p class="note">Revenue is a planning scenario before discounts, channel fees and returns. All produced units remain part of the production commitment.</p></div>`;}
function pantoneLibraryView(){return `<section class="panel pantone-library"><div class="panel-head"><div><span class="eyebrow">Your colour references</span><h2>Pantone reference library</h2></div><a class="button small" href="https://connect.pantone.com/" target="_blank" rel="noopener">Open Pantone Connect ↗</a></div><p class="note">Import your authorised shade data to browse and add Pantone references to your palette. TCX is a textile reference; TPG is a paper reference. No Pantone catalogue is bundled with Forecut.</p><div class="actions"><button class="primary" data-action="importPantone">Import shade CSV</button><button data-action="pantoneTemplate">Download CSV template</button><button data-action="exportPantone">Export my references</button></div><input id="pantoneFile" type="file" accept=".csv,text/csv" hidden><div class="fields two" style="margin-top:20px"><label>Search your imported shades<input id="pantoneSearch" type="search" placeholder="Name or reference code…" autocomplete="off"></label><label>Colour system<select id="pantoneSystemFilter"><option value="all">All systems</option>${ForecutColourLibrary.systems.map(s=>`<option>${s}</option>`).join('')}</select></label></div><div id="pantoneLibraryResults" aria-live="polite"></div><p class="note">Imported HEX values are screen previews, not a verified conversion to a physical Pantone shade. Confirm the code and material with your physical reference or Pantone Connect.</p></section>`;}
function paletteView(){return `<section class="panel palette-intro"><div><span class="eyebrow">Colour Palette Builder</span><h2>Colour, with a reference.</h2><p class="note">Build a palette from the forecast, add your own colours and keep physical reference codes with every shade.</p><a class="button small" href="#pantoneLibraryResults">Browse my Pantone references ↓</a></div><img src="tools/thumbnails/palette.svg" alt="A fan of fabric colour swatches" width="960" height="640"></section>${pantoneLibraryView()}<section class="panel"><div class="panel-head"><h2>Your collection palette</h2><button class="primary" data-action="addColour">+ Add colour</button></div><div class="fields two no-print">${select('Start from an unlocked forecast','forecast','',(window.ForecutPalettes||[]).map(p=>[p.season,p.title]))}<div><span class="note">Add colours without replacing your palette</span><div class="actions"><button data-action="loadForecast">Add forecast colours</button></div></div></div><p class="note">Source: ${escape(state.paletteSource)}. Approve physical lab dips before production.</p><div class="swatches">${state.palette.map(c=>{const ink=M.contrast(c.hex,'#ffffff')>=4.5?'#ffffff':'#111111';return `<article class="swatch" data-colour="${c.id}"><div class="colour-block" style="background:${c.hex};color:${ink}"><span>${escape(c.hex.toUpperCase())}</span>${c.pantoneCode?`<span>${escape(c.pantoneCode)} ${escape(c.pantoneSystem||'TCX')}</span>`:''}</div><div class="swatch-body"><label>Colour name<input data-colour-field="name" value="${escape(c.name)}" maxlength="80"></label><div class="fields two"><label>Picker<input type="color" data-colour-field="picker" value="${c.hex}"></label><label>HEX preview<input data-colour-field="hex" value="${c.hex}" pattern="#[a-fA-F0-9]{6}" maxlength="7"></label></div><label>Palette role<select data-colour-field="role">${['Core','Accent','Print ground','Print colour'].map(r=>`<option ${r===c.role?'selected':''}>${r}</option>`).join('')}</select></label><details class="reference-fields" ${c.pantoneCode?'open':''}><summary>${c.pantoneCode?'Edit Pantone reference':'Add Pantone reference'}</summary><label>System<select data-colour-field="pantoneSystem">${ForecutColourLibrary.systems.map(s=>`<option ${(c.pantoneSystem||'TCX')===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Reference code<input data-colour-field="pantoneCode" value="${escape(c.pantoneCode||'')}" placeholder="From your physical reference" maxlength="40"></label><label>Reference name (optional)<input data-colour-field="pantoneName" value="${escape(c.pantoneName||'')}" maxlength="120"></label><span class="note">Adding a code records your reference; it does not verify a colour match.</span></details><div class="note">RGB ${M.rgb(c.hex).join(', ')}<br>CMYK ≈ ${M.cmyk(c.hex).map(Math.round).join(' / ')}%</div><button class="small danger" data-action="removeColour" data-id="${c.id}">Remove colour</button></div></article>`;}).join('')}</div>${state.palette.length?'':'<p class="empty">Add a colour, load a forecast or choose an imported shade.</p>'}<div class="actions"><button data-action="paletteCSV">Export palette CSV</button><button data-action="paletteSVG">Download swatch sheet SVG</button>${printButton}</div></section><section class="panel"><h2>Colour combinations</h2><p class="note">Role-based starting points for your collection. Choose the combinations that suit your design.</p><div id="combinations"></div></section><section class="panel"><h2>Text readability check</h2><p class="note">For text and labels on a colour ground. Clothing palettes do not need to pass a text contrast test.</p><div class="fields two">${select('Text colour','contrastA',state.palette[0]?.id||'',state.palette.map(c=>[c.id,c.name]))}${select('Background','contrastB',state.palette[1]?.id||state.palette[0]?.id||'',state.palette.map(c=>[c.id,c.name]))}</div><div id="contrastResult"></div><p class="note">CMYK is an unprofiled approximation. Use your printer’s colour profile and a physical reference for production.</p></section>`;}
function pantoneResults(){const host=$('#pantoneLibraryResults');if(!host)return;const q=($('#pantoneSearch')?.value||'').trim().toLowerCase(),system=$('#pantoneSystemFilter')?.value||'all',library=state.pantoneLibrary||[];const matches=library.map((c,i)=>({...c,index:i})).filter(c=>(system==='all'||c.system===system)&&(!q||(c.name+' '+c.code+' '+c.system).toLowerCase().includes(q)));host.innerHTML=library.length?`<p class="note">${matches.length} matching shades${matches.length>48?' · Showing the first 48. Search to narrow the list.':''}</p><div class="reference-grid">${matches.slice(0,48).map(c=>`<button type="button" class="reference-tile" data-action="addPantone" data-id="${c.index}"><span style="background:${c.hex}"></span><b>${escape(c.name)}</b><small>${escape(c.code)} ${escape(c.system)}</small><em>Add to palette +</em></button>`).join('')}</div>${matches.length?'':'<p class="empty">No matching references. Try a name or code.</p>'}`:'<div class="empty"><strong>Your shade library starts here.</strong><p>Import a CSV with code, name, hex and system columns. You can also add a Pantone reference directly to any palette colour below.</p></div>';}
function paletteResults(){const core=state.palette.filter(c=>c.role==='Core'),accents=state.palette.filter(c=>c.role==='Accent'),pairs=[];for(const c of core)for(const a of accents)if(pairs.length<6)pairs.push([c,a]);$('#combinations').innerHTML=pairs.length?pairs.map(([c,a])=>`<div style="display:inline-flex;margin:5px 12px 5px 0;align-items:center;gap:7px"><span style="background:${c.hex};width:27px;height:27px;border:1px solid #bbb;border-radius:50%"></span><span style="background:${a.hex};width:27px;height:27px;border:1px solid #bbb;border-radius:50%"></span><span class="note">${escape(c.name)} + ${escape(a.name)}</span></div>`).join(''):'<p class="note">Assign at least one core colour and one accent to see combinations.</p>';contrastResult();pantoneResults();}
function contrastResult(){const a=state.palette.find(c=>c.id===$('[data-field="contrastA"]')?.value),b=state.palette.find(c=>c.id===$('[data-field="contrastB"]')?.value);if(!a||!b){$('#contrastResult').textContent='Add two colours to compare.';return;}const ratio=M.contrast(a.hex,b.hex);$('#contrastResult').innerHTML=`<p style="padding:20px;background:${b.hex};color:${a.hex};border:1px solid var(--line);border-radius:6px">Collection label preview · ${escape(a.name)}</p><p class="note">Contrast ${ratio.toFixed(2)}:1 · Small text: ${ratio>=4.5?'passes':'below 4.5:1'} · Large text: ${ratio>=3?'passes':'below 3:1'}</p>`;}
function evenView(){const e=state.even;return `${styleChooser()}<section class="panel"><h2>Order assumptions</h2><label class="check"><input type="checkbox" id="linkPrice" ${e.linked?'checked':''}>Use this style’s Price & Profit Calculator cost and net revenue before product cost</label><p class="note">The two values below remain linked while this is selected. Product cost is deducted once.</p><div class="fields">${[['Collection fixed costs','fixed'],['Variable production cost / piece','variable'],['Net revenue / kept piece BEFORE product cost','proceeds'],['Minimum order / pieces made','quantity'],['Expected sell-through (%)','sellThrough'],['Unsold recovery (% of net revenue / piece)','recovery']].map(([l,k])=>field(l,k,e[k],{scope:'even',min:k==='quantity'?1:0,step:k==='quantity'?1:'any',max:['sellThrough','recovery'].includes(k)?100:undefined})).join('')}</div><p class="note">Fixed costs can include sampling, design and photography. If importing Price & Profit Calculator, sell-through is the share of produced units ultimately kept by customers; its return burden is already included. Unsold recovery means net liquidation proceeds after liquidation fees.</p></section><div id="evenResults" aria-live="polite"></div><section class="panel"><div class="actions"><button data-action="evenCSV">Export scenarios CSV</button>${printButton}</div><details><summary>Formulas</summary><div class="formula">Contribution per kept piece = net revenue before product cost − variable production cost<br>Investment = fixed costs + quantity × variable production cost<br>Profit = sold × net revenue + unsold × recovery × net revenue − investment<br>Break-even sales with no unsold recovery = ceiling(fixed costs ÷ contribution)<br>Sell-through needed at this order size = (investment − quantity × recovery × net revenue) ÷ (quantity × net revenue × (1 − recovery))</div></details></section>`;}
function evenInputs(){const e=state.even;if(e.linked){const r=M.price(priceInputs(state.price));if(r.netRevenue<0)throw Error('Price & Profit Calculator net revenue is negative. Improve the selling assumptions or unlink this calculation.');e.variable=r.cost;e.proceeds=r.netRevenue;for(const k of ['variable','proceeds']){const el=$(`[data-scope="even"][data-field="${k}"]`);if(el){el.value=e[k].toFixed(2);el.disabled=true;}}}else for(const k of ['variable','proceeds']){const el=$(`[data-scope="even"][data-field="${k}"]`);if(el)el.disabled=false;}return {...e,sellThrough:e.sellThrough/100,recovery:e.recovery/100};}
function evenResults(){try{const x=evenInputs(),r=M.breakEven(x);let required=r.required===null?(r.profitAt(0)>=0?'Already covered by recovery':'Impossible under these assumptions'):r.required<=0?'0%':r.required>1?'Above 100% — not achievable':pct(r.required);$('#evenResults').innerHTML=`<div class="metrics">${metric('Upfront commitment',money(r.investment),'Fixed costs + all units made')}${metric('Profit at planned sell-through',money(r.profit),'At '+pct(x.sellThrough)+' kept sales',r.profit<0)}${metric('Sell-through to break even',required,'For this order quantity',r.required>1)}</div>${r.contribution<=0?'<p class="notice">Net revenue does not cover variable production cost. Selling more at this price cannot cover fixed costs through normal sales.</p>':''}<section class="panel"><h2>What if fewer pieces sell?</h2><p class="note">Contribution per sold piece: ${money(r.contribution)}. Conventional break-even: ${r.breakEven===null?'unavailable':num(r.breakEven)+' sold pieces'} with no unsold recovery and production matched to sales. The order-specific threshold above also pays for unsold inventory.</p>${profitChart(x,r)}<table><thead><tr><th>Sell-through</th><th>Kept units</th><th>Profit / loss</th></tr></thead><tbody>${[.25,.5,.75,1].map(s=>`<tr><td>${pct(s)}</td><td>${num(x.quantity*s)}</td><td>${money(r.profitAt(x.quantity*s))}</td></tr>`).join('')}</tbody></table><h3 style="margin-top:22px">Compare order sizes</h3><table><thead><tr><th>Quantity</th><th>Investment</th><th>Profit at ${pct(x.sellThrough)}</th></tr></thead><tbody>${[1,1.5,2].map(f=>{const q=Math.ceil(x.quantity*f),a=M.breakEven({...x,quantity:q});return `<tr><td>${q}</td><td>${money(a.investment)}</td><td>${money(a.profit)}</td></tr>`;}).join('')}</tbody></table></section>`;}catch(e){$('#evenResults').innerHTML=`<p class="error">${escape(e.message)}</p>`;}}
function profitChart(x,r){const vals=[r.profitAt(0),r.profitAt(x.quantity)],lo=Math.min(0,...vals),hi=Math.max(1,...vals),y=v=>160-(v-lo)/(hi-lo)*130,z=y(0);return `<svg class="chart" viewBox="0 0 660 205" role="img" aria-label="Profit rises from ${escape(money(vals[0]))} at zero sales to ${escape(money(vals[1]))} at full sell-through"><line x1="75" y1="${z}" x2="630" y2="${z}" stroke="#cbbbad" stroke-dasharray="5 5"/><path d="M75 ${y(vals[0])} L630 ${y(vals[1])}" fill="none" stroke="#38644c" stroke-width="3"/><text x="5" y="${y(vals[0])+4}">${escape(money(vals[0]))}</text><text x="500" y="${Math.max(15,y(vals[1])-10)}">${escape(money(vals[1]))}</text><text x="75" y="190">0 kept units</text><text x="520" y="190">${num(x.quantity)} kept units</text><text x="5" y="${z-6}">₹0</text></svg>`;}
function weekends(s){return s==='sat-sun'?[0,6]:s==='none'?[]:[0];}
function holidayList(s){return s.split(/[\s,]+/).filter(Boolean);}
function calendarView(){const c=state.calendar;return `<section class="panel"><h2>Launch brief</h2><div class="fields">${field('Target launch / listing date','launch',c.launch,{type:'date',scope:'calendar'})}${select('Non-working days','weekends',c.weekends,[['sun','Sundays'],['sat-sun','Saturdays & Sundays'],['none','Work every day']],'calendar')}${field('Minimum lead-time buffer (calendar days)','buffer',c.buffer,{scope:'calendar',step:1})}<label style="grid-column:1/-1">Holidays / factory closures (YYYY-MM-DD, separated by commas)<textarea data-field="holidays" data-scope="calendar" placeholder="2027-01-26, 2027-08-15">${escape(c.holidays)}</textarea></label></div><p class="note">This first version schedules tasks sequentially. Durations are editable examples in working days. Add transit and approval time explicitly; Sundays / selected weekends and your listed holidays are skipped.</p></section><div id="calendarResults" aria-live="polite"></div><section class="panel"><div class="panel-head"><h2>Production steps</h2><button data-action="addTask">+ Add step</button></div><div class="table-scroll"><table><thead><tr><th>Step</th><th>Working days</th><th>Order / remove</th></tr></thead><tbody>${c.tasks.map((t,i)=>`<tr data-task="${t.id}"><td><input aria-label="Task name" data-task-field="name" value="${escape(t.name)}" maxlength="100"></td><td><input aria-label="Working days" type="number" min="1" max="365" step="1" data-task-field="days" value="${t.days}"></td><td style="white-space:nowrap"><button class="small" data-action="taskUp" data-id="${t.id}" ${i===0?'disabled':''} aria-label="Move ${escape(t.name)} earlier">↑</button> <button class="small" data-action="taskDown" data-id="${t.id}" ${i===c.tasks.length-1?'disabled':''} aria-label="Move ${escape(t.name)} later">↓</button> <button class="small danger" data-action="removeTask" data-id="${t.id}" ${c.tasks.length===1?'disabled':''}>Remove</button></td></tr>`).join('')}</tbody></table></div><div class="actions"><button class="primary" data-action="calendarICS">Download calendar (.ics)</button><button data-action="calendarCSV">Export schedule CSV</button>${printButton}</div><p class="note">Calendar events use inclusive task dates, exported as all-day events. Import into Google Calendar, Apple Calendar or Outlook. Re-importing uses stable event IDs.</p></section>`;}
function getSchedule(){return M.schedule(state.calendar.launch,state.calendar.tasks,weekends(state.calendar.weekends),holidayList(state.calendar.holidays));}
function calendarResults(){try{const rows=getSchedule(),today=localDate(),start=rows[0].start,last=rows.at(-1).end,span=(+M.parseDate(last)-M.parseDate(start))/86400000+1;const buffer=(+M.parseDate(start)-M.parseDate(today))/86400000;$('#calendarResults').innerHTML=`<div class="metrics">${metric('Start by',formatDate(start),'First production milestone',start<today)}${metric('Working days',num(rows.reduce((a,t)=>a+t.days,0)),rows.length+' sequential steps')}${metric('Scheduled finish',formatDate(last),'Launch target '+formatDate(state.calendar.launch))}</div>${start<today?'<p class="notice">This schedule needs to have started already. Move the launch date or confirm shorter supplier lead times.</p>':buffer<state.calendar.buffer?'<p class="notice">The first task starts within your minimum buffer. Confirm supplier availability.</p>':''}${last!==state.calendar.launch?'<p class="notice">The target falls on a non-working day. The schedule finishes on the previous working day.</p>':''}<section class="panel"><h2>Your route to launch</h2><div class="timeline">${rows.map(t=>{const offset=(+M.parseDate(t.start)-M.parseDate(start))/86400000,days=(+M.parseDate(t.end)-M.parseDate(t.start))/86400000+1;return `<div class="timeline-item ${t.start<today?'past':''}"><span>${escape(t.name)}</span><div class="bar-track"><div class="bar" style="margin-left:${offset/span*100}%;width:${Math.max(1,days/span*100)}%"></div></div><span>${formatDate(t.start)} – ${formatDate(t.end)}</span></div>`;}).join('')}</div><details><summary>Full dated schedule</summary><table><thead><tr><th>Task</th><th>Start</th><th>Finish</th><th>Working days</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${escape(t.name)}</td><td>${t.start}</td><td>${t.end}</td><td>${t.days}</td></tr>`).join('')}</tbody></table></details></section>`;}catch(e){$('#calendarResults').innerHTML=`<p class="error">${escape(e.message)}</p>`;}}
function formatDate(s){return M.parseDate(s).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});}
function render(){document.querySelectorAll('[data-tab]').forEach(a=>{if(a.dataset.tab===current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});app.innerHTML=heading()+({pricefold:priceView,rangeboard:rangeView,swatchsmith:paletteView,evenpoint:evenView,cutclock:calendarView}[current])();$('#collectionName').value=state.name;$('#printCollection').textContent=state.name+' · '+new Date().toLocaleDateString('en-IN');update();}
function update(){({pricefold:priceResults,rangeboard:rangeResults,swatchsmith:paletteResults,evenpoint:evenResults,cutclock:calendarResults}[current])();}
function go(tool){syncPrice();save();current=tool;history.pushState({tool},'',tool+'.html');document.title=titles[tool][0]+' | Forecut';render();window.scrollTo({top:0,behavior:'instant'});}
function reportError(e){toast(e.message||'Please check your inputs.');}
function validInput(el){el.setCustomValidity('');if(el.type==='number'&&(el.value===''||!Number.isFinite(el.valueAsNumber))){el.reportValidity();return false;}if(!el.checkValidity()){el.reportValidity();return false;}return true;}
function processField(el){
 if(!validInput(el)){const result=app.querySelector('[id$=Results]');if(result)result.innerHTML='<p class="error">Please complete the highlighted input to update your results.</p>';return;}
 const key=el.dataset.field,scope=el.dataset.scope;
 let value=el.type==='checkbox'?el.checked:el.type==='number'?el.valueAsNumber:el.value;
 if(key==='contrastA'||key==='contrastB'){contrastResult();return;}
 if(!scope)return;
 if(scope==='calendar'){
  const next={...state.calendar,[key]:value};
  try{M.schedule(next.launch,next.tasks,weekends(next.weekends),holidayList(next.holidays));}
  catch(e){el.setCustomValidity(e.message);const result=$('#calendarResults');if(result)result.innerHTML='<p class="error">'+escape(e.message)+'</p>';return;}
 }
 if(scope==='range'&&key.startsWith('share'))state.range.shares[+key.slice(5)]=value;
 else state[scope][key]=value;
 if(scope==='price')syncPrice();
 update();save();
}
app.addEventListener('input',e=>{const el=e.target;if(el.id==='pantoneSearch'){pantoneResults();return;}if(el.dataset.scope&&el.type!=='checkbox'&&el.tagName!=='SELECT'&&!(el.dataset.scope==='calendar'&&['launch','holidays'].includes(el.dataset.field)))processField(el);});
app.addEventListener('change',e=>{const el=e.target;
 try{
 if(el.id==='pantoneSystemFilter'){pantoneResults();return;}
 if(el.id==='pantoneFile'){importPantoneFile(el.files[0]);return;}
 if(el.id==='styleSelect'){state.activeStyle=el.value;const s=state.styles.find(s=>s.id===el.value);if(s)state.price={...s.priceSettings};save();render();return;}
 if(el.id==='linkPrice'){state.even.linked=el.checked;update();save();return;}
 if(el.dataset.field)processField(el);
 if(el.dataset.styleField){if(!validInput(el))return;const s=state.styles.find(s=>s.id===el.closest('[data-style]').dataset.style),k=el.dataset.styleField;s[k]=el.type==='number'?el.valueAsNumber:el.value;if(k==='price')s.priceSettings.mrp=s.price;if(k==='cost'){s.priceSettings={...s.priceSettings,fabric:s.cost,stitching:0,trims:0,packaging:0,other:0,overhead:0};}if(s.id===state.activeStyle)state.price={...s.priceSettings};rangeResults();save();}
 if(el.dataset.colourField){const c=state.palette.find(c=>c.id===el.closest('[data-colour]').dataset.colour),k=el.dataset.colourField;if(k==='hex'||k==='picker'){M.rgb(el.value);c.hex=el.value.toLowerCase();}else if(k==='pantoneCode'){c.pantoneCode=ForecutColourLibrary.codeValue(el.value,c.pantoneSystem||'TCX');}else c[k]=el.value;save();render();}
 if(el.dataset.taskField){if(!validInput(el))return;const t=state.calendar.tasks.find(t=>t.id===el.closest('[data-task]').dataset.task);t[el.dataset.taskField]=el.type==='number'?el.valueAsNumber:el.value;calendarResults();save();}
 }catch(e){reportError(e);}
});
async function importPantoneFile(file){if(!file)return;try{if(file.size>3000000)throw Error('Choose a CSV smaller than 3 MB.');const imported=ForecutColourLibrary.importCSV(await file.text()),map=new Map((state.pantoneLibrary||[]).map(c=>[c.system+'|'+c.code,c]));for(const c of imported)map.set(c.system+'|'+c.code,c);if(map.size>5000)throw Error('Keep no more than 5,000 shades in this collection.');state.pantoneLibrary=[...map.values()];save();render();toast(imported.length+' shade references imported.');}catch(e){reportError(e);}finally{const input=$('#pantoneFile');if(input)input.value='';}}
const actions={
 print:()=>window.print(),
 importPantone:()=>$('#pantoneFile').click(),
 pantoneTemplate:()=>download('colour-reference-template.csv','code,name,hex,system\r\n','text/csv;charset=utf-8'),
 exportPantone:()=>csv(slug()+'-colour-references.csv',[['code','name','hex','system'],...(state.pantoneLibrary||[]).map(c=>[c.code,c.name,c.hex,c.system])]),
 addPantone:index=>{const c=(state.pantoneLibrary||[])[Number(index)];if(!c)throw Error('Shade reference not found.');if(state.palette.length>=100)throw Error('Maximum 100 palette colours.');state.palette.push({id:uid(),name:c.name,hex:c.hex,role:'Accent',pantoneCode:c.code,pantoneSystem:c.system,pantoneName:c.name});save();render();toast(c.code+' '+c.system+' added to your palette.');},
 solve:()=>{const r=M.solvePrice(priceInputs(state.price),state.price.target/100,state.price.ending9);state.price.mrp=r.mrp;syncPrice();save();render();toast('Target price applied: '+money(r.mrp));},
 sendEven:()=>{const r=M.price(priceInputs(state.price));if(r.netRevenue<0)throw Error('Net revenue is negative. Improve your price or fees before using Break-even Calculator.');state.even.linked=true;state.even.variable=r.cost;state.even.proceeds=r.netRevenue;go('evenpoint');},
 priceCSV:()=>{const p=state.price,r=M.price(priceInputs(p));csv(slug()+'-price-and-profit.csv',[['Collection',state.name],['Style',state.styles.find(s=>s.id===state.activeStyle)?.name||'Standalone'],['Currency','INR'],['Assumption','Value'],...Object.entries(p),['Output','INR / ratio'],...Object.entries(r)]);},
 addStyle:()=>{if(state.styles.length>=500)throw Error('Maximum 500 styles per collection.');state.styles.push(newStyle());save();render();},
 removeStyle:id=>{const s=state.styles.find(s=>s.id===id);if(!confirm('Remove '+s.name+' from this collection?'))return;state.styles=state.styles.filter(s=>s.id!==id);if(state.activeStyle===id)state.activeStyle='';save();render();},
 priceStyle:id=>{state.activeStyle=id;state.price={...state.styles.find(s=>s.id===id).priceSettings};go('pricefold');},
 calendarStyle:id=>{const s=state.styles.find(s=>s.id===id);if(!s.drop)throw Error('Set a drop date for this style first.');state.calendar.launch=s.drop;go('cutclock');toast('Launch date set from '+s.name);},
 allocate:()=>{const r=state.range;if(r.plannedStyles<1||r.plannedStyles>200)throw Error('Choose 1–200 new slots.');const counts=M.allocate(r.plannedStyles,r.shares);if(state.styles.length+r.plannedStyles>500)throw Error('Maximum 500 styles per collection.');counts.forEach((n,i)=>{for(let j=0;j<n;j++){const s=newStyle();s.category=categories[i];s.name=categories[i]+' '+(j+1);state.styles.push(s);}});save();render();},
 rangeCSV:()=>csv(slug()+'-collection-plan.csv',[['Collection',state.name],['Season',state.range.season],['Market',state.range.market],['Style','Category','Tier','Trend stage','Colourways','Sizes','Units per SKU','Total units','MRP INR','Cost INR','Drop date'],...state.styles.map(s=>[s.name,s.category,s.tier,s.stage,s.colours,s.sizes,s.perSku,s.colours*s.sizes*s.perSku,s.price,s.cost,s.drop])]),
 addColour:()=>{if(state.palette.length>=100)throw Error('Maximum 100 colours.');state.palette.push({id:uid(),name:'New colour',hex:'#c9a227',role:'Accent'});save();render();},
 removeColour:id=>{state.palette=state.palette.filter(c=>c.id!==id);save();render();},
 loadForecast:()=>{const p=(window.ForecutPalettes||[]).find(p=>p.season===$('[data-field="forecast"]').value);if(!p)return;const colours=p.colours.filter(c=>!state.palette.some(x=>x.hex.toLowerCase()===c.hex.toLowerCase()));if(state.palette.length+colours.length>100)throw Error('Maximum 100 colours.');state.palette.push(...colours.map(c=>({...c,id:uid(),role:'Core'})));state.paletteSource+='; '+p.title+' forecast';save();render();toast(colours.length+' forecast colours added.');},
 paletteCSV:()=>csv(slug()+'-palette.csv',[['Collection',state.name],['Source',state.paletteSource],['Name','Role','HEX preview','R','G','B','C approx %','M approx %','Y approx %','K approx %','Pantone code','Pantone system','Pantone reference name'],...state.palette.map(c=>[c.name,c.role,c.hex,...M.rgb(c.hex),...M.cmyk(c.hex).map(Math.round),c.pantoneCode||'',c.pantoneSystem||'',c.pantoneName||''])]),
 paletteSVG:()=>{const height=120+Math.ceil(state.palette.length/3)*235;const xml=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="${height}" viewBox="0 0 900 ${height}"><rect width="900" height="100%" fill="#f7f4ee"/><text x="30" y="40" font-family="Georgia" font-size="25">${escape(state.name)} · Forecut</text><text x="30" y="67" font-family="sans-serif" font-size="12">Screen colours are a guide. Approve physical lab dips before production.</text>${state.palette.map((c,i)=>{const x=30+(i%3)*290,y=95+Math.floor(i/3)*235;return `<g transform="translate(${x} ${y})"><rect width="260" height="130" rx="4" fill="${c.hex}"/><text y="155" font-family="sans-serif" font-size="16">${escape(c.name.slice(0,25))}</text><text y="177" font-family="sans-serif" font-size="12">${c.hex.toUpperCase()} · ${escape(c.role)}</text><text y="215" font-family="sans-serif" font-size="10">${escape(c.pantoneCode?c.pantoneCode+' '+(c.pantoneSystem||'TCX'):'No physical reference assigned')}</text><text y="196" font-family="sans-serif" font-size="11">RGB ${M.rgb(c.hex).join(' / ')}</text></g>`;}).join('')}</svg>`;download(slug()+'-swatch-sheet.svg',xml,'image/svg+xml');},
 evenCSV:()=>{const x=evenInputs();M.breakEven(x);csv(slug()+'-break-even.csv',[['Collection',state.name],['Fixed cost',x.fixed],['Variable cost per piece',x.variable],['Net revenue BEFORE product cost',x.proceeds],['Quantity','Sell-through','Kept units','Investment INR','Profit INR'],...[1,1.5,2].flatMap(f=>[.25,.5,.75,1].map(s=>{const q=Math.ceil(x.quantity*f),r=M.breakEven({...x,quantity:q,sellThrough:s});return[q,s,q*s,r.investment,r.profit];}))]);},
 addTask:()=>{if(state.calendar.tasks.length>=100)throw Error('Maximum 100 tasks.');state.calendar.tasks.push({id:uid(),name:'New step',days:2});save();render();},
 removeTask:id=>{if(state.calendar.tasks.length<=1)return;state.calendar.tasks=state.calendar.tasks.filter(t=>t.id!==id);save();render();},
 taskUp:id=>moveTask(id,-1),taskDown:id=>moveTask(id,1),
 calendarCSV:()=>csv(slug()+'-production-schedule.csv',[['Collection',state.name],['Target launch',state.calendar.launch],['Step','Start','Finish','Working days'],...getSchedule().map(t=>[t.name,t.start,t.end,t.days])]),
 calendarICS:()=>{const rows=getSchedule(),stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z');const icsEscape=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Forecut//Production Calendar//EN','CALSCALE:GREGORIAN',...rows.flatMap(t=>{const end=M.parseDate(t.end);end.setUTCDate(end.getUTCDate()+1);return['BEGIN:VEVENT','UID:'+t.id+'@forecut.in','DTSTAMP:'+stamp,'LAST-MODIFIED:'+stamp,'DTSTART;VALUE=DATE:'+t.start.replace(/-/g,''),'DTEND;VALUE=DATE:'+end.toISOString().slice(0,10).replace(/-/g,''),'SUMMARY:'+icsEscape(t.name+' · '+state.name),'DESCRIPTION:'+icsEscape('Forecut Production Calendar: '+t.days+' working days. Confirm dates with your suppliers.'),'END:VEVENT'];}),'END:VCALENDAR'];const fold=s=>{let out='',line='',bytes=0;for(const ch of s){const n=new TextEncoder().encode(ch).length;if(bytes+n>73){out+=line+'\r\n';line=' ';bytes=1;}line+=ch;bytes+=n;}return out+line;};download(slug()+'-production.ics',lines.map(fold).join('\r\n')+'\r\n','text/calendar;charset=utf-8');}
};
function moveTask(id,d){const a=state.calendar.tasks,i=a.findIndex(t=>t.id===id),j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];save();render();}
app.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){try{const invalid=app.querySelector('input:invalid,select:invalid,textarea:invalid');if(invalid){invalid.reportValidity();return;}actions[a.dataset.action]?.(a.dataset.id);}catch(e){reportError(e);}}const link=e.target.closest('[data-go]');if(link){e.preventDefault();go(link.dataset.go);}});
document.querySelectorAll('[data-tab]').forEach(a=>a.addEventListener('click',e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();go(a.dataset.tab);}));
window.addEventListener('popstate',()=>{const t=location.pathname.split('/').pop().replace('.html','');current=titles[t]?t:'pricefold';render();});
$('#collectionName').addEventListener('input',e=>{state.name=e.target.value;$('#printCollection').textContent=state.name;save();});
$('#backup').onclick=()=>{syncPrice();download(slug()+'-backup.json',JSON.stringify(state,null,2),'application/json');toast('Backup downloaded. Keep it somewhere safe.');};
$('#restore').onclick=()=>$('#restoreFile').click();
$('#restoreFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>3000000)throw Error('Backup is too large (maximum 3 MB).');const next=validateBackup(JSON.parse(await f.text()));if(!confirm('Replace the current browser collection with “'+next.name+'”? Download a backup first if you want to keep your current work.'))return;state=next;saveFailed=false;save();render();toast('Collection restored.');}catch(e){reportError(e);}finally{$('#restoreFile').value='';}};
$('#print').onclick=()=>window.print();
window.addEventListener('storage',e=>{if(e.key===KEY){saveFailed=true;$('#status').textContent='This collection changed in another tab. Reload before editing; automatic saving is paused to protect the newer copy.';}});
render();
})();
